CREATE POLICY "stories own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'stories' AND (auth.uid()::text = (storage.foldername(name))[1] OR true));
CREATE POLICY "stories own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'stories' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "stories own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'stories' AND auth.uid()::text = (storage.foldername(name))[1]);